35: /**
36:  * Fixed-capacity particle pool backed by one Points draw call.
37:  * Call emit() for bursts and update() once per render frame.
38:  */
39: export class ParticleManager {
40:   readonly points: THREE.Points<THREE.BufferGeometry, THREE.PointsMaterial>;
41:   readonly capacity: number;
