58:   constructor(options: ParticleManagerOptions = {}) {
59:     const capacity = Math.floor(options.capacity ?? 256);
60:     if (!Number.isFinite(capacity) || capacity < 1) {
61:       throw new Error('ParticleManager capacity must be a positive finite integer');
62:     }
63: 
64:     this.capacity = capacity;
65:     this.defaultGravity = options.gravity ?? -9.81;
66:     this.positions = new Float32Array(capacity * 3);
