78:     const geometry = new THREE.BufferGeometry();
79:     geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
80:     geometry.setAttribute('color', new THREE.BufferAttribute(this.colors, 3));
81:     geometry.setDrawRange(0, capacity);
82:     for (let index = 0; index < capacity; index += 1) {
83:       this.free[index] = capacity - index - 1;
84:       this.writeInactive(index);
85:     }
86:     geometry.attributes.position.needsUpdate = true;
87: 
88:     const material = new THREE.PointsMaterial({
89:       color: 0xffffff,
90:       size: options.pointSize ?? 0.12,
91:       sizeAttenuation: true,
92:       vertexColors: true,
93:       transparent: true,
94:       opacity: options.opacity ?? 1,
95:       depthWrite: options.depthWrite ?? false,
96:     });
97:     this.points = new THREE.Points(geometry, material);
