111:   emit(options: ParticleSpawnOptions): number {
112:     if (this.disposed) return 0;
113:     const count = Math.max(0, Math.floor(options.count ?? 1));
114:     const lifetime = Math.max(0.001, options.lifetime ?? 0.65);
115:     const velocity = options.velocity ?? DEFAULT_VELOCITY;
116:     const color = options.color ?? DEFAULT_COLOR;
117:     const spread = Math.max(0, options.spread ?? 0);
118:     const random = options.random ?? Math.random;
119:     let emitted = 0;
120: 
121:     while (emitted < count && this.freeCount > 0) {
122:       const index = this.free[--this.freeCount];
123:       const offset = index * 3;
124:       const xJitter = spread === 0 ? 0 : (random() * 2 - 1) * spread;
125:       const yJitter = spread === 0 ? 0 : (random() * 2 - 1) * spread;
126:       const zJitter = spread === 0 ? 0 : (random() * 2 - 1) * spread;
127:       this.positions[offset] = options.position.x + xJitter;
128:       this.positions[offset + 1] = options.position.y + yJitter;
129:       this.positions[offset + 2] = options.position.z + zJitter;
130:       this.velocities[offset] = velocity.x;
131:       this.velocities[offset + 1] = velocity.y;
132:       this.velocities[offset + 2] = velocity.z;
133:       this.colors[offset] = this.baseColors[offset] = color.r;
134:       this.colors[offset + 1] = this.baseColors[offset + 1] = color.g;
